+        std::iter::Once<&EngineCoreStreamOutput>,
+        std::slice::Iter<'_, EngineCoreStreamOutput>,
+    > {
+        match self {
+            Self::One(output) => Either::Left(std::iter::once(output)),
+            Self::Many(outputs) => Either::Right(outputs.iter()),
+        }
+    }
+}
